def _apply(source: int, target: int) -> None:
    conn = op.get_bind()
    for filename, contents in CHANGES.items():
        result = conn.execute(
            sa.text(
                "UPDATE route_server_templates SET content = :new, updated_at = now() "
                "WHERE filename = :filename AND content = :old"
            ),
            {"new": contents[target], "old": contents[source], "filename": filename},
        )
        total = conn.execute(
            sa.text("SELECT count(*) FROM route_server_templates WHERE filename = :filename"),
            {"filename": filename},
        ).scalar_one()
        untouched = total - result.rowcount
        if untouched:
            print(
                f"aviso: {untouched} de {total} plantillas {filename} estaban "
                "editadas y quedaron como estaban"
            )


def upgrade() -> None:
    _apply(0, 1)


def downgrade() -> None:
    _apply(1, 0)
